3 - وردت في النص الفرنسي عبارة"des délits et des quasi-délits"" "عن الجرائم وأشباه الجرائم بدل
"عن الجرائم وعن أشباه الجرائم" كما جاء في الترجمة العربية؛ فالجريمة (الخطأ العمدي) وشبه الجريمة (الخطأ
غير العمدي)، مصدر واحد من مصادر الالتزام الذي يطلق عليه العمل غير المشروع؛ مطابقة مع عنوان الباب
الثالث الذي ورد فيه: "الالتزامات الناشئة عن الجرائم وأشباه الجرائم".
وبذلك يمكن صياغة الفصل 1 :أعلاه كالآتي تنشأ الالتزامات عن الاتفاقات والتصريحات الأخرى المعبرة عن
الإرادة وعن أشباه العقود وعن الجرائم وأشباه الجرائم.
4 - وردت في النص الفرنسي عبارة" les éléments" "العناصر" بدل الأركان كما جاء في الترجمة العربية؛
فالعناصر تستغرق الأركان وشروط الصحة، أما الأركان فهي أجزاء الماهية التي تختل باختلال بعضها.
والملاحظ أن الأهلية من حيث المبدأ ليست ركنا، لأنها لا تعتبر من أجزاء الماهية وإنما من شروط الصحة.
وبذلك يمكن صياغة الفقرة 1 من الفصل2 :أعلاه كالآتي العناصر اللازمة لصحة الالتزامات الناشئة عن التعبير
