وفق الشروط المنصوص عليها في الفصلين 417-1 و 417-2أدناه6.
يمكن للملتزم، عندما يطلب منه بيان مكتوب بيده، أن يقوم بتحريره بشكل إلكتروني إذا
كان من شأن شروط تحريره ضمان أنه الوحيد الذي يمكنه القيام بذلك.
