القانون7.، ماعدا المحررات المنجزة من لدن شخص لأغراض مهنته$art$, 2, $art$pdf-text-layer$art$, 0.576, 5, 6, $art$الباب الأول: الالتزامات التي تنشأ عن الاتفاقات والتصريحات الأخرى$art$),
