الخدمات عن بعد، وذلك على صفحة الاستقبال في الموقع الإلكتروني لمورد السلعة أو مقدم الخدمة أو على أية
دعامة اتصال تتضمن عرضا للمورد. كما يجب أن تكون هذه الشروط موضوع قبول صريح من طرف المستهلك
