40- قارن مع المادة29 من القانون رقم31.08 سالف الذكر والتي تنص على أنه: "دون الإخلال بالمعلومات
المنصوص عليها في المادتين 3 و5 أو في أي نص تشريعي أو تنظيمي آخر جاري به العمل، يجب أن يتضمن
العرض المتعلق بعقد البيع عن بعد المعلومات التالية:
1- التعريف بالمميزات الأساسية للمنتوج أو السلعة أو الخدمة محل العرض ؛
2- اسم المورد وتسميته التجارية والمعطيات الهاتفية التي تمكن من التواصل الفعلي معه وبريد ه الالكتروني
وعنوانه وإذا تعلق الأمر بشخص معنوي فمقره الاجتماعي، وإذا تعلق الأمر بغير المورد فعنوان المؤسسة
المسؤولة عن العرض ؛
بالنسبة للتاجر السيبراني :
- إذا كان خاضعا لشكليات القيد في السجل التجاري، فرقم تسجيله ورأسمال الشركة؛
- إذا كان خاضعا للضريبة على القيمة المضافة، فرقم تعريفه الضريبي؛
- وإذا كان نشاطه خاضعا لنظام الترخيص، فرقم الرخصة وتاريخها والسلطة التي سلمتها ؛
- إذا كان منتميا لمهنة منظمة، فمرجع القواعد المهنية المطبقة وصفته المهنية والبلد الذي حصل فيه على هذه
الصفة وكذا اسم الهيئة أو التنظيم المهني المسجل فيه.
3- أجل التسليم ومصاريفه إن اقتضى الحال ؛
4- وجود حق التراجع المنصوص عليه في المادة36 ، ما عدا في الحالات التي تستثنى فيها أحكام هذا الباب
ممارسة الحق المذكور؛
5- كيفيات الأداء أو التسليم أو التنفيذ ؛
6- مدة صلاحية العرض وثمنه أو تعريفته ؛
7- تكلفة استعمال تقنية الاتصال عن بعد ؛
8- المدة الدنيا للعقد المقترح، إن اقتضى الحال، عندما يتعلق الأمر بتزويد مستمر أو دوري لمنتوج أو سلعة أو
خدمة.
1 - الخصائص الأساسية للسلعة أو الخدمة المقترحة أوالأصل التجاري المعني أو أحد
عناصره ؛
2 - شروط بيع السلعة أو الخدمة أو شروط تفويت الأصل التجاري أو أحد عناصره ؛
3 - مختلف المراحل الواجب اتباعها لإبرام العقد بطريقة إلكترونية ولا سيما الكيفية
التي يفي طبقها الأطراف بالتزاماتهم المتبادلة ؛
4 - الوسائل التقنية التي تمكن المستعمل المحتمل، قبل إبرام العقد، من كشف الأخطاء
المرتكبة أثناء تحصيل المعطيات وتصحيحها ؛
5 - اللغات المقترحة من أجل إبرام العقد41 ؛
6 - طريقة حفظ العقد في الأرشيف من لدن صاحب العرض وشروط الاطلاع على
العقد المحفوظ إذا كان من شأن طبيعة العقد أو الغرض منه تبرير ذلك ؛
7 - وسائل الاطلاع، بطريقة إلكترونية، على القواعد المهنية والتجارية التي يعتزم
صاحب العرض الخضوع لها، عند الاقتضاء.
كل اقتراح غير متضمن لكافة البيانات المشار إليها في هذا الفصل لا يجوز اعتباره
عرضا بل يبقى مجرد إشهار، ولا يلزم صاحبه.$art$, 69, $art$pdf-text-layer$art$, 0.632, 19, 20, $art$الفرع الثاني: العرض$art$),
  ($art$65-5$art$, $art$الفصل 65-5$art$, $art$يشترط لصحة إبرام العقد أن يكون من أرسل العرض إليه قد تمكن من التحقق من
تفاصيل الإذن الصادر عنه ومن سعره الإجمالي ومن تصحيح الأخطاء المحتملة، وذلك قبل
تأكيد الإذن المذكور لأجل التعبير عن قبوله.
يجب على صاحب العرض الإشعار بطريقة إلكترونية، ودون تأخير غير مبرر،
وبطريقة إلكترونية، بتسلمه قبول العرض الموجه إليه.
يصبح المرسل إليه فور تسلم العرض ملزما به بشكل لا رجعة فيه.
يعتبر قبول العرض وتأكيده والإشعار بالتسلم متوصلا بها إذا كان بإمكان الأطراف
المرسلة إليهم الولوج إليها.
تبلغ المعلومات المذكورة، التي يجب أن يتجلى طابعها التجاري دون التباس، إلى المستهلك بصورة واضحة
ومفهومة عن طريق كل وسيلة ملائمة للتقنية المستخدمة للاتصال عن بعد.
دون الإخلال بمقتضيات القانون رقم 53.05 المتعلق بالتبادل الالكتروني للمعطيات القانونية، يجب على المورد
أن يذكر المستهلك قبل إبرام العقد بمختلف اختياراته، وأن يمكنه من تأكيد طلبيته أو تعديلها حسب إرادته.
