فحسب، لكن يكون مسؤولا أيضا عن الضرر الذي يحدثه الأشخاص الذين هم في عهدته.
الأب فالأم بعد موته، يسألان عن الضرر الذي يحدثه أبناؤهما القاصرون الساكنون
معهما.
المخدومون ومن يكلفون غيرهم برعاية مصالحهم يسألون عن الضرر الذي يحدثه
خدامهم ومأموروهم في أداء الوظائف التي شغلوهم فيها.
أرباب الحرف يسألون عن الضرر الحاصل من متعلميهم خلال الوقت الذي يكونون
فيه تحت رقابتهم.
وتقوم المسؤولية المشار إليها أعلاه، إلا إذا أثبت الأب أو الأم وأرباب الحرف أنهم لم
يتمكنوا من منع وقوع الفعل الذي أدى إليها.
الأب والأم وغيرهما من الأقارب أو الأزواج يسألون عن الأضرار التي يحدثها
المجانين وغيرهم من مختلي العقل، إذا كانوا يسكنون معهم، ولو كانوا بالغين سن الرشد.
وتلزمهم هذه المسؤولية ما لم يثبتوا:
1 - أنهم باشروا كل الرقابة الضرورية على هؤلاء الأشخاص؛
2 - أو أنهم كانوا يجهلون خطورة مرض المجنون؛
3 - .أو أن الحادثة قد وقعت بخطأ المتضرر
ويطبق نفس الحكم على من يتحمل بمقتضى عقد رعاية هؤلاء الأشخاص أو رقابتهم.$art$, 92, $art$pdf-text-layer$art$, 0.622, 25, 25, $art$الباب الثالث: الالتزامات الناشئة عن الجرائم وأشباه الجرائم$art$),
  ($art$85-مكرر$art$, $art$الفصل 85-مكرر$art$, $art$(ظهير 4 مايو1942) يسأل المعلمون وموظفو الشبيبة والرياضة عن الضرر
الحاصل من الأطفال والشبان خلال الوقت الذي يوجدون فيه تحت رقابتهم.
والخطأ أو عدم الحيطة أو الإهمال الذي يحتج به عليهم، باعتباره السبب في حصول
الفعل الضار، يلزم المدعي إثباته وفقا للقواعد القانونية العامة.
وفي جميعالحالات التي تقوم فيها مسؤولية رجال التعليم العام وموظفي إدارة الشبيبة
نتيجة ارتكاب فعل ضار أو بمناسبته إما من الأطفال أو من الشبان الذين عهد بهم إليهم بسبب
وظائفهم وإما ضدهم في نفس الأحوال، تحل مسؤولية الدولة محل مسؤولية الموظفين
السابقين، الذين لا تجوز مقاضاتهم أبدا أمام المحاكم المدنية من المتضرر أو من ممثله.
ويطبق هذا الحكم في كل حالة يعهد فيها بالأطفال أو الشبان إلى الموظفين السابق
ذكرهم قصد التهذيب الخلقي أو الجسدي الذي لا يخالف الضوابط، ويوجدون بذلك تحت
رقابتهم، دون اعتبار لما إذا وقع الفعل الضار في أوقات الدراسة أم خارجها.
ويجوز للدولة أن تباشر دعوى الاسترداد، إما على رجال التعليم وموظفي إدارة
الشبيبة وإما على الغير، وفقا للقواعد العامة.
ولا يسوغ، في الدعوى الأصلية، أن تسمع شهادة الموظفين الذين يمكن أن تباشر الدولة
ضدهم دعوى الاسترداد.
وترفع دعوى الم سؤولية التي يقيمها المتضرر أو أقاربه أو خلفاؤه ضد الدولة
