65 - انظر على سبيل المثال الفصل488 :من قانون المسطرة المدنية التي ينص على أنه
« يمكن لكل دائن ذاتي أو اعتباري يتوفر على دين ثابت إجراء حجز بين يدي الغير بإذن من القاضي على مبالغ
ومستندات لمدينه والتعرض على تسليمها له.
غير أنه لا يقبل التحويل والحجز فيما يلي:
1 - التعويضات التي يصرح القانون بأنها غير قابلة للحجز؛
2 - النفقات؛
3 - المبالغ التي تسبق أو ترد باعتبارها مصاريف مكتب أو جولة أو تجهيز أو تنقل أو نقل؛
4 - المبالغ الممنوحة باعتبارها ردا لتسبيقات أو أداء لمصاريف أنفقها عامل مستخدم بصفة مستمرة أو مؤقتة
بمناسبة عمله؛
5 - المبالغ الممنوحة باعتبارها ردا لتسبيقات أو أداء لمصاريف سينفقها الموظفون أو الأعوان المساعدون في
تنفيذ مصلحة عامة أو مصاريف أنفقوها بمناسبة عملهم؛
6 - جميع التعويضات والمنح وجميع ما يضاف أو يلحق بالأجور والرواتب كتعويضات عائلية؛
2 - إذاكان محلها حقوقا لها صفة شخصية محضة، كحق انتفاع المستحق لحبس؛
3 - إذاكان الدين لا يقبل الحجز أو التعرض. إلا أنه إذا كان الدين لا يقبل الحجز إلا
في حدود جزء منه محدد أو قيمة محددة، صحت الحوالة في حدود هذه النسبة.$art$, 212, $art$pdf-text-layer$art$, 0.616, 48, 49, $art$الباب الأول: الانتقال بوجه عام$art$),
  ($art$192$art$, $art$الفصل 192$art$, $art$.تبطل حوالة الحق المتنازع فيه، ما لم تتم بموافقة المدين المحال عليه
ويعتبر الحق متنازعا فيه، في معنى هذا الفصل، إذا كان هناك نزاع في جوهر الحق أو
الدين نفسه عند البيع أو الحوالة، أو كانت هناك ظروف من شأنها أن تجعل من المتوقع إثارة
منازعات قضائية جدية حول جوهر الحق نفسه.$art$, 213, $art$pdf-text-layer$art$, 0.655, 49, 49, $art$الباب الأول: الانتقال بوجه عام$art$),
