التوصيل أن الوفاء قد وقع بالنقود أو الشيء المقدم من الدائن الجديد لهذا الغرض. وفي حالة
الإيداع، يجب ذكر البيانات السابقة في التوصيل المدفوع من أمين الودائع؛
