الكلفة أو صعبا. وإذا كان من الممكن نقل محل الالتزام، دون صعوبة، ساغ للمدين أن يقوم
بالوفاء أينما وجد الدائن ما لم يكن للدائن مبرر معقول في عدم قبول الوفاء المعروض عليه.
