طبقا للفصل 1098 من قانون الالتزامات والعقود، يتنازل فيه الأجير عن أي أداء وجب لفائدته بفعل تنفيذ العقد أو
بفعل إنهائه.» وكذا الفقرة الثانية من المادة76 من مدونة الشغل التي تنص على أنه: « يعتبر الإبراء أو الصلح،
طبقا للفصل 1098 من قانون الالتزامات والعقود، مجرد وثيقة بالمبالغ المبينة فيها.»
