تتقادم بخمس سنوات : دعوى التجار والموردين وأرباب المصانع بسبب التوريدات
التي يقدمونها لغيرهم من التجار أو الموردين أو أرباب المصانع من أجل حاجات مهنهم.
تتقادم بسنتين:
1 - دعوى الأطباء والجراحين والمولدين وأطباء الأسنان والبياطرة من أجل ما
يقومون به من زيارات ويؤدونه من عمليات، وكذلك من أجل ما يوردونه من أشياء وما
يقدمونه من نقود ابتداء من تاريخ حصوله؛
2 - دعوى الصيادلة من أجل الأدوية التي يوردونها، ابتداء من تاريخ توريدها؛
3 - دعوى المؤسسات الخاصةأو العامة المخصصة لعلاج الأمراض البدنية أو العقلية
أو لرعاية المرضى، من أجل العلاج المقدم منها لمرضاها والتوريدات والمصروفات
الحاصلة منها لهم، ابتداء من تاريخ تقديم العلاج أو حصول التوريدات؛
4 - دعوى المهندسين المعماريين وغيرهم من المهندسين والخبراء والمساح ين من
أجل مواصفاتهم أو عملياتهم والمصروفات المقدمة منهم ابتداء من تاريخ تقديم المواصفة أو
إتمام العمليات أو إجراء المصروفات؛
5 - دعوى التجار والموردين وأرباب المصانع من أجل التوريدات المقدمة منهم
للأفراد لاستعمالهم الخاص؛
6 - دعوى الفلاحين ومنتجي المواد الأولية من أجل التوريدات المقدمة منهم، إذا كانت
قد استخدمت في الأغراض المنزلية للمدين، وذلك ابتداء من يوم وقوع التوريدات.
تتقادم بسنة ذات ثلاثمائة وخمسة وستين يوما:
1 - دعوى المعلمين والأساتذة وأصحاب المؤسسات المخصصة لإقامة التلاميذ العامة
منها والخاصة، من أجل أتعابهم المستحقة على تلاميذهم وكذلك من أجل التوريدات المقدمة
منهم إليهم، وذلك ابتداء من حلول الأجل المحدد لدفع أتعابهم؛
2 - دعوى الخدم 103 من أجل أجورهم وما قاموا به من مصروفات وغير ذلك من
الأداءات المستحقة لهم بمقتضى عقد إجارة العمل، وكذلك دعوى المخدومين ضد خدامهم من
أجل المبالغ التي يسبقونها لهم على أساس تلك الرابطة؛
