وعن الخلافات الفردية التي لها علاقة بهذه العقود، أيا كانت طبيعة هذه الحقوق، سواء كانت نابعة عن تنفيذ هذه
العقود أو عن إنهائها.»
3 - دعوى العمال والمستخدمين والمتعلمين والمتجولين ومندوبي التجارة
والصناعة104 ، من أجل رواتبهم وعمولاتهم، وما أدوه من مصروفات بسبب وظائفهم، وما
يستحقونه من عطلة سنوية مؤدى عنها أو ما يعوضها وذلك عن السنة الجارية وعند ثبوت
الحق في عطل مجتمعة، عن السنة أو السنتين الماضيتين؛
دعوى أرباب الحرف من أجل توريداتهم ومياوماتهم وما أنفقوه بسبب خدماتهم؛
دعوى المخدوم أو رب العمل من أجل المبالغ المسبقة للعمال والمستخدمين والمتعلمين
والمتجولين والمندوبين من أجورهم أو عمولاتهم أو المبالغ التي أنفقوها بسبب خدماتهم؛
4 - دعوى أصحاب الفنادق والمطاعم، من أجل الإقامة والطعام وما يصرفونه لحساب
زبنائهم؛
5 - .دعوى مكري المنقولات من أجل أجرتها$art$, 400, $art$pdf-text-layer$art$, 0.642, 85, 86, $art$الباب السابع: التقادم$art$),
