:تتقادم أيضا بسنة ذات ثلاثمائة وخمسة وستين يوما
1 - دعوى وكلاء الخصومة، من أجل الأتعاب، والمبالغ التي يصرفونها وذلك ابتداء
من الحكم النهائي أو من عزلهم من الوَكالة 105؛
2 - دعوى الوسطاء من أجل استيفاء السمسرة، ابتداء من إبرام الصفقة؛
3 - دعوى المتعاقدين ضد الأشخاص المذكورين فيما سبق، من أجل ما سبقوه لهم،
لأداء ما أنيط بهم من أعمال، وذلك ابتداء من نفس التاريخ المقرر لكل طائفة منهم؛
4 - الدعاوى التي تثبت من أجل العوار والضياع والتأخير وغيرها من الدعاوى التي
يمكن أن تنشأ عن عقد النقل، سواء أكانت ضد الناقل أو الوكيل بالعمولة أو ضد المرسل أو
المرسل إليه، وكذلك الدعاوى التي تنشأ بمناسبة عقد النقل.
وتحسب مدة هذا التقادم، في حالة الهلاك الكلي، ابتداء من اليوم الذي كان يجب فيه
تسليم البضاعة، وفي غير ذلك من الأحوال، ابتداء من يوم تسليم البضاعة للمرسل إليه أو
عرضها عليه.
