تصبح الوثيقة رسمية إذا وضع التوقيع المذكور عليها أمام موظف عمومي له صلاحية
التوثيق.
عندما يكون التوقيع إلكترونيا، يتعين استعمال وسيلة تعريف موثوق بها تضمن
