يعتبر التوقيع الإلكتروني مؤمنا109 إذا تم إنشاؤه وكانت هوية الموقع مؤكدة وتمامية
الوثيقة القانونية مضمونة، وفق النصوص التشريعية والتنظيمية المعمول بها في هذا المجال.
تتمتع كل وثيقة مذيلة بتوقيع إلكتروني مؤمن والمختومة زمنيا بنفس قوة الإثبات التي
