1- هوية الأطراف المتعاقدة؛
2- محل المخابرة المتفق عليه مع وجوب الإخبار في حالة تغييره؛
3- رقمالرسم العقاري الأصلي للعقار المحفظظ موضظوع البنظاء أو مراجظع ملكيظة العقظار
غير المحفظ مع تحديد الحقوق العينية والتحملات والارتفاقات170 الواردة على العقار171؛
4- تاريخ ورقم رخصة البناء؛
5- موقع العقار محل البيع ووصفه ومساحته التقريبية؛
6- ثمظن البيظع النهظائي للمتظر المربظع وكيفيظة الأداء أو ثمظن البيظع الإجمظالي بالنسظبة للبيظع
المتعلق باقتناء عقار في إطار السكن الاجتماعي كما هو محدد بالتشريع الجاري به العمل؛
7- أجل التسليم؛
8- مراجعضمانة استرجاع الأقساط المؤداة في حالة عظدم تنفيظذ البظائع للعقظد أو ضظمانة
إنهاء الأشغال أو التأمين.
يودع البائع لدى محرر العقد، قصد الاطلاع، نسخا مطابقة ل لأصل من التصاميم
المعمارية الحاملة لعبارة "غير قابل للتغيير" وتصاميم الإسمنت المسلح ونسخة من دفتر
التحملات ونسخة من الضمانة البنكية أو أي ضمانة أخرى مماثلة أو التأمين.
وتقوم الضمانة المشار إليها في الفقرة الأولى أعلاه بقوة القانون، وعلى الرغم من كل
مقتضى مخالف، مقام أي حجز تحفظي يجريه المشتري في نطاق تطبيق أحكام هذا القانون
إذا كانت الضمانة المذكورة من شأنها أن تغطي الحقوق موضوع هذا الحجز التحفظي.
مرتين
يمكن للبائع والمشتري قبل تحرير العقد الابتدائي إبرام عقد تخصيص من أجل اقتناء
عقار في طور الإنجاز يحرر إما في محرر رسمي أو محرر عرفي ثابت التاريخ وفقا للشكل
المتفق عليه من الأطراف.
لا يجوز إبرام عقد تخصيص العقار في طور الإنجاز، تحت طائلة البطلان، إلا بعد
الحصول على رخصة البناء.
