171 - ينص الفصل 62 من الظهير الشريف الصادر في 9 رمضان1331 (12 أغسطس1913 ) المتعلق
بالتحفيظ العقاري على ما يلي: "إن الرسم العقاري نهائي ولا يقبل الطعن، ويعتبر نقطة الانطلاق الوحيدة للحقوق
العينية والتحملات العقارية المترتبة على العقار وقت تحفيظه دون ما عداها من الحقوق غير المقيدة".
يتضمن عقد التخصيص البيانات الواردة في البنود 1 و2 و3 و4 و5 و6 و7
المنصوص عليها في الفصل618.3 .مكرر أعلاه
ثلاث مرات
يحق للمشتري التراجع عن عقد التخصيص داخل أجل لا يتعدى شهرا ابتداء من تاريخ
إبرام عقد التخصيص.
يجب على البائع في حالة تراجع المشتري عن عقد التخصيص، أن يرجع للمشتري
المبلغ المدفوع كاملا داخل أجل لا يتعدى سبعة أيام ابتداء من تاريخ ممارسة هذا الحق.
وتحدد صلاحية عقد التخصيص في مدة لا تتجاوز ستة (6 ) أشهر غير قابلة للتجديد
تؤدي لزوما إلى إبرام عقد البيع الابتدائي أو التراجع عن عقد التخصيص واسترجاع المبالغ
المسبقة.
يودع البائع المبالغ المالية المؤداة من طرف المشترين عند إبرام عقود التخصيص،
وذلك في الحدود المقررة في الفصل 6-618 أدناه في حساب بنكي خاص في اسم البائع.
وتكون هذه المبالغ المالية المودعة غير قابلة للتصرف أو الحجز إلى حين انقضاء أجل حق
التراجع المتعلق بكل عقد. وفي المقابل يتسلم المشتري وصلا بالإيداع.$art$, 638, $art$pdf-text-layer$art$, 0.627, 134, 135, $art$الفرع الرابع: بيع العقارات في طور الإنجاز162$art$),
  ($art$618-4$art$, $art$الفصل 618-4$art$, $art$يجب على البائع أن يضع دفتر تحملات العقار مطابقا للتصميم المعماري المرخص به
يتضمن مكونات المشروع وما أعد له ونوع الخدمات والتجهيزات التي يتوجب إنجازها
وأجل الإنجاز والتسليم.
يوقع البائع والمشتري على دفتر التحملات مع تصحيح إمضائهما بعد إطلاع المهندس
المعماري عليه وتسلم نسخة للمشتري مشهود بمطابقتها للأصل.
يرفق دفتر التحملات، عند الاقتضاء، ببطاقة تقنية موجزة موقعة من قبل البائع تتضمن
وصفا لمكونات محل نموذجي منجز من طرفه.
إذا كان العقار محفظا، تودع نسخ من هذا الدفتر ومن التصاميم المعمارية الحاملة
لعبارة "غير قابل للتغيير" وتصاميم الإسمنت المسلح ومن نظام الملكية المشتركة ، عند
الاقتضاء، بالمحافظة على الأملاك العقارية.
إذا كان العقار غير محفظ، تودع وتسجل هذه النسخ بسجل خاص لدى كتابة الضبط
بالمحكمة الابتدائية التي يوجد بدائرتها العقار.
