تحدد شروط وكيفيات تطبيق هذا الفصل بنص تنظيمي.
يتحلل البائع بقوة القانون من الالتزام بالضمانة بمجرد تقييد عقد البيع النهائي أو الحكم
القضائي النهائي بالسجل العقاري إذا كان العقار محفظا أو إيداعه بمطلب التحفيظ إذا كان
العقار في طور التحفيظ أو بمجرد إبرام العقد وصدور الحكم القضائي النهائي إذا كان العقار
غير محفظ.
يتحلل البائع من الالتزام بالضمانة بمجرد صدور حكم نهائي بالفسخ ناتج عن رفض
المشتري تنفيذ التزاماته المنصوص عليها في عقد البيع الابتدائي أو إتمام البيع بعد استيفاء
الإجراءات المنصوص عليها في المادة 18-618 .أدناه
لا يجوز لمحرر العقد الإفراج عن الأقساط المودعة لديه لفائدة البائع إلا بعد حصوله
من طرف هذا الأخير على الضمانة التي تغطي كل قسط يؤديه المشتري.
في حالة تحلل البائع من التزامه بالضمانة، يتعين على محرر العقد الابتدائي للبيع،
إرجاع سند أو سندات الضمانة أو التأمين إلى البائع بمجرد توصله بطلب خطي من هذا
الأخير، ترفق معه الوثائق التي تثبت الحالتين أعلاه.$art$, 644, $art$pdf-text-layer$art$, 0.658, 137, 137, $art$الفرع الرابع: بيع العقارات في طور الإنجاز162$art$),
  ($art$618-10$art$, $art$الفصل 618-10$art$, $art$يجوز للمشتري، إذا كان العقار محفظا، أن يطلب إجراء تقييد احتياطي بناء على عقد
البيع الابتدائي إذا تجاوزت التسبيقات 50% من ثمن البيع. ويبقى التقييد الاحتياطي ساريا
إلى غاية تقييد عقد البيع النهائي وذلك للحفاظ المؤقت على حقوق المشتري. وكل شرط
مخالف يعتبر باطلا.
يبقى التقييد الاحتياطي ساري المفعول إلى غاية تقييد عقد البيع النهائي بالرسم العقاري
الخاص بالمبيع.
بمجرد إجراء التقييد الاحتياطي، يمنع على المحافظ على الأملاك العقارية تسليم نظير
الرسم العقاري إلى البائع.
