أولا - الانتفاع بالشيء المكترى وحيازته بلا معارض؛
ثانيا - استحقاق الشيء والعيوب التي تشوبه.
ويثبت هذا الضمان بقوة القانون، وإن لم يشترط، ولا يحول حسن نية المكري دون
قيامه.$art$, 686, $art$pdf-text-layer$art$, 0.586, 146, 146, $art$الفرع الثاني: آثار الكراء$art$),
  ($art$644$art$, $art$الفصل 644$art$, $art$الالتزام بالضمان، يقتضي، بالنسبة إلى المكري، التزامه بالامتناع عن كل ما يؤدي إلى
تعكير صفو حيازة المكتري، أو إلى حرمانه من المزايا التي كان من حقه أن يعول عليها
بحسب ما أعد له الشيء المكترى والحالة التي كان عليها عند العقد.
وفي هذا المجال، يسأل المكري ليس فقط عن فعله وفعل أتباعه بل أيضا عن أفعال
الانتفاع التي يجريها المكترون الآخرون أو غيرهم ممن تلقوا الحق عنه.
195 - وردت في النص الفرنسي عبارة"des réparations réputées locatives" الإصلاحات المعتبرة
كرائية بدل "إصلاحات الصيانة المعتبرة بسيطة " كما جاء في الترجمة العربية.
وبذلك يمكن صياغة الفصل 640 :أعلاه كالآتي لا يتحمل المكتري أي شيء من الإصلاحات المعتبرة كرائية إذا
تسبب عن القدم أو القوة القاهرة أو خطأ في البناء أو عن فعل المكري.
Aucune des réparations réputées locatives n'est à la charge du preneur quand
elles sont occasionnées par vétusté ou force majeure, par le vice de c onstruction
ou par le fait du bailleur.
