للمكتري الفرعي، أو حتى للغير.
وله أن يعترض على نقل هذه الأشياء، بالالتجاء إلى السلطة المختصة. ويسوغ له أن
يستردها، إذا نقلت بغير علمه أو برغ م معارضته بقصد إعادتها إلى المكان الذي كانت
موجودة فيه، أو وضعها في مستودع آخر.
