اللازمة لضمانه. وليس له حق التتبع إذا كانت الأشياء الباقية في المحلات المكتراة تكفي
لتأمين حقوقه.
ولا تجوز مباشرة حق الاسترداد بعد خمسة عشر يوما من وقت علم المكري بحصول
النقل.
ولا تجوز مباشرة حق الحبس أو الاسترداد:
أ - على الأشياء التي لا يمكن إجراء حجز المنقول عليها؛
ب - على الأشياء المسروقة أو الضائعة؛
ج - على الأشياء المملوكة للغير، إذا كان المكري يعل م عند إدخالها إلى المحلات
المكتراة، بأنها مملوكة لذلك الغير.$art$, 727, $art$pdf-text-layer$art$, 0.67, 154, 154, $art$الفرع الثاني: آثار الكراء$art$),
