خطإه، والعيب الناتج من استعمالها على نحو عاد مألوف.
وإذا كان المكتري، خلال مدة الكراء، قد استبدل بالأشياء الهالكة أشياء أخرى مكانها،
أو أصلح ما تعيب، حق له أن يسترد ما أنفقه ما لم يكن هناك خطأ يعزى إليه.$art$, 764, $art$pdf-text-layer$art$, 0.625, 161, 161, $art$الفرع الرابع: عقود الكراء الفلاحية$art$),
  ($art$722$art$, $art$الفصل 722$art$, $art$إذا أكمل المكتري من ماله الأدوات المخصصة للاستغلال، بأن أضاف إليها أدوات
أخرى لم تذكر في قائمة الإحصاء ثبت للمالك، عند نهاية الكراء الخيار بين أن يدفع له قيمة
هذه الأدوات الأخيرة مقدرة على نحو ما يقرره أهل الخبرة، وبين أن يردها له في الحالة التي
هي عليها.
