237 - قارن مع المواد143 و144 و145 و147 .من مدونة الشغل
ثالثا: باستحالة التنفيذ الناشئة إما بسبب حادث فجائي أو قوة قاهرة وإما بسبب وفاة
مؤجر الصنعة أو الخدمة، مع مراعاة ما يقضي به القانون من استثناءات بالنسبة إلى الحالة
الأخيرة، ولا تنفسخ الإجارتان بموت السيد أو رب العمل238.$art$, 787, $art$pdf-text-layer$art$, 0.643, 166, 167, $art$الفرع الأول: أحكام عامة$art$),
  ($art$745-مكرر$art$, $art$الفصل 745-مكرر$art$, $art$(ظهير 8 أبريل1938)
لا لكل من يقدم خدماته بمقتضى عقد أن يطلب عند انقضائه من رب العمل، شهادة
تتضمن إلا تاريخ التحاقه بالخدمة وتاريخ تركه إياها وتقديره المهني خلال الستة الأشهر
الأخيرة السابقة لانقضاء العقد. فإن لم تقدم له هذه الشهادة، حق له التعويض.
تعفى شهادات العمل المعطاة للعمال والمستخدمين والخدم من التمبر والتسجيل، ولو
اشتملت على بيانات أخرى غير تلك المذكورة في الفقرة السابقة ماد امت هذه البيانات لا
تتضمن التزاما ولا توصيلا ولا أي اتفاق آخر مما يخضع للتمبر أو للتسجيل.
ويشمل الإعفاء الرسم الذي يتضمن عبارة "حر من كل التزام" أو أي صياغة أخرى
تثبت انقضاء عقد العمل انقضاء طبيعيا والصفات المهنية والخدمات المؤداة239.
مرتين
(ظهير 6 يوليوز1954 ) التوصيل الذي يعطيه العامل لرب العمل، عند فسخ أو
انقضاء عقده، بتصفية كل حساباته تجاهه، يجوز نقضه خلال الثلاثين يوما التالية لتوقيعه.
يبطل كل ما يصدر من الأجير في التوصيل من تنازل عن المكافآت الممنوحة عن
العطل السنوية المدفوعة وعن المكافآ ت المستحقة له تعويضا عن العطل التي لم يأخذها،
وعن المكافآت والمزايا المقررة بمقتضى العقد الجماعي والتي مازالت مستحقة له، وعن
التعويضات التي قد تستحق له نتيجة إنهاء العقد بمقتضى الفصل 754 :التالي
يلزم أن يتضمن التوصيل البيانات الآتية، وإلا وقع باطلا:
أ - جملة المبلغ المدفوع للأجير تصفية لكل حساباته مكتوبا بخط يده. كما يلزم على
الأجير أن يكتب قبل توقيعه عبارة " قرئ وصودق عليه ". وإذا كان الأجير أميا، استبدل
بتوقيعه توقيع شاهدين يختارهما بنفسه؛
ب - ميعاد السقوط المذكور في الفقرة الأولى مكتوبا بحروف تقرأ بوضوح؛
ج - أنه حرر في نظيرين أعطي أحدهما للأجير.
ويلزم إجراء نقض التوصيل إما بخطاب مضمون موجه لرب العمل، وإما برفع
الدعوى أمام محكمة الشغل وعند عدم اختصاصها، أمام محكمة السدد240 لاوهو لا يصلح إ
بشرط توضيح الحقوق المختلفة التي يدعيها الأجير لنفسه.
