248 - قارن مع المواد1 إلى11 من القانون رقم18.12 المتعلق بالتعويض عن حوادث الشغل، الصادر بتنفيذه
الظهير الشريف رقم 1.14.190 في6 ربيع الأول 1436 (29 ديسمبر2014 )، الجريدة الرسمية عدد6328
بتاريخ فاتح ربيع الأول1436 (22 يناير2015 ) ص489 .$art$, 794, $art$pdf-text-layer$art$, 0.591, 169, 169, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$752$art$, $art$الفصل 752$art$, $art$يسوغ إنقاص التعويض، إذا ثبت أن الحادثة التي كان الأجير ضحيتها قد تسببت عن
عدم حيطته أو عن خطإه وتزول مسؤولية المخدوم كلية، ولا يمنح أي تعويض للأجير، إذا
كان سبب الحادثة راجعا إلى سكره أو إلى خطإه الجسيم249.$art$, 795, $art$pdf-text-layer$art$, 0.632, 170, 170, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$753$art$, $art$الفصل 753$art$, $art$( ظهير6 يوليوز1954)
تنقضي إجارة الخدمة بانقضاء المدة التي حددها الطرفان250.
إذا ارتضى المتعاقدان صراحة عند إبرام عقد محدد المدة، إمكانية تجديده وحددا عدد
مرات التجديد، لم يسغ لهما أن يحددا لكل من هذه المرات مدة تتجاوز المدة التي حددت للعقد
ومن غير أن تزيد في أي حالة على سنة. والعقد الذي يبرم لمدة محددة يمكن أن يمتد بالتجديد
الضمني إلى ما بعد أجله المشروط. وفي هذه الحالة يصبح غير محدد المدة251.$art$, 796, $art$pdf-text-layer$art$, 0.633, 170, 170, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$754$art$, $art$الفصل 754$art$, $art$(ظهير26 شتنبر1938) إذا لم تحدد مدة العقد، وكان ذلك راجعا إلى إرادة المتعاقدين
أو إلى طبيعة العمل اللازم أداؤه، فإن العقد يقع قابلا للإبطال، ويسوغ لأي من المتعاقدين أن
يتخلص منه بإعطائه تنبيها بذلك للطرف الآخر في المواعيد التي يقررها العرف252 المحلي
أو الاتفاق. ويستحق الأجر بن سبة الخدمات المؤداة، وعلى حسب ما هو مستحق للأعمال
المماثلة253.
يسوغ في إجارة الخدمة، بمقتضى الاتفاقات الجماعية 254 ، مخالفة المواعيد المحددة
بمقتضى العرف255.
كل شرط يحدد في عقد فردي أو في ضابط مصنع ميعادا للتنبيه أدنى مما هو مقرر
بمقتضى العرف256 أو بمقتضى الاتفاقاتالجماعية يقع باطلا بقوة القانون257.
فسخ العقد بإرادة أحد المتعاقدين وحده يمكن أن يؤدي إلى التعويض258.
