التعويضات التي يمكن أن تمنح بسبب عدم مراعاة ميعاد التنبيه لا تختلط بالتعويضات
التي قد تترتب، من ناحية أخرى، عن الفسخ التعسفي للعقد الصادر بإرادة أحد الطرفين
المتعاقدين259 . ويسوغ للمحكمة، في سبيل تقدير ما إذا كان يوجد فسخ، أن تجري تحقيقا في
ظروف إنهاء العقد 260 . ويلزم في جميع الأحوال، أن يتضمن الحكم صراحة ذكر المبرر
الذي يدعيه الطرف الذي أنهى العقد.
لتحديد التعويض، عندما يكون له محل، تلزم مراعاة العرف 261 وطبيعة الخدمات
وأقدمية أدائها، وسن الأجير أو المستخدم والمخصومات المقتطعة والمدفوعات الحاصلة من
أجل ترتيب معاش التقاعد، وعلى العموم كل الظروف التي تبرر وجود الخسارة الحاصلة
وتحدد مداها262.
إذا طرأ تغيير في المركز القانوني لرب العمل، وعلى الأخص بسبب الإرث أو البيع أو
الإدماج أو تحويل المشروع، أو تقديمه حصة في شركة فإن جميع عقود العمل الجارية في
يوم حصول هذا التغيير تستمر بين المالك الجديد للمشروع وبين عماله وخدمه
ومستخدميه263.
توقف المشروع، لسبب آخر غير القوة القاهرة، لا يعفي صاحبه من الالتزام باحترام
ميعاد التنبيه264.
لا يصح التنازل مقدما من الطرفين عن الحق الذي قد يثبت لأحدهما في طلب
التعويضات وفقا لما تقضي به الأحكام السابقة265.
إذا رفعت المنازعات الناشئة عن تطبيق أحكام الفقرات السابقة أمام المحاكم المدنية أو
محكمة الاستيناف266 .وجب التحقيق والحكم فيها على وجه السرعة
الامتياز ال مقرر بمقتضى البند 4 من267 الفصل1248 التالي يضمن التعويضات
المنصوص عليها في هذا الفصل، سواء كانت بسبب عدم مراعاة ميعاد التنبيه أو بسبب
الفسخ التعسفي للعقد.
