267 - قارن مع المادة382 : من مدونة الشغل التي تنص على أنه
تطبق أحكام هذا الفصل، حتى في الحالة التي يرتبط فيها المستخدم بمقتضى عقود
إجارة بعدة أرباب أعمال.$art$, 797, $art$pdf-text-layer$art$, 0.644, 170, 172, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$755$art$, $art$الفصل 755$art$, $art$في تعهدات العمال أو الخدم وعمال المتاجر وخدام المحلات العمومية تعتبر الخمسة
عشر يوما الأولى فترة تجربة، ويجوز خلالها لأي من الطرفين بمحض رغبته إبطال العقد،
دون أن يلتزم بتعويض ما، وإذا أراد أحد الطرفين إبطال العقد، وجب عليه أن يعلم الآخر
برغبته بيومين مقدما. وهنا يستحق المستخدم أجره على حسب عمله268.
ويطبق كل ما سبق، إلا إذا قضى العرف269 .المحلي أو الاتفاق بخلافه$art$, 798, $art$pdf-text-layer$art$, 0.591, 172, 172, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$756$art$, $art$الفصل 756$art$, $art$في إجارة الخدمة يعتبر الشرط الفاسخ موجودا، دون حاجة للنص عليه، لصالح كل من
المتعاقدين، إذا لم ينفذ المتعاقد الآخر التزاماته أو للأسباب ا لخطيرة الأخرى التي يترك
تقديرها للقضاة.$art$, 799, $art$pdf-text-layer$art$, 0.631, 172, 172, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$757$art$, $art$الفصل 757$art$, $art$للمخدوم الحق في فسخ العقد للمرض أو للإصابة التي تلحق خادمه أو مستخدمه نتيجة
قوة قاهرة، على أن يدفع لهذا الأخير ما يستحقه بنسبة مدة خدمته270.$art$, 800, $art$pdf-text-layer$art$, 0.706, 172, 172, $art$الفرع الثاني: إجارة الخدمة أو العمل$art$),
  ($art$758$art$, $art$الفصل 758$art$, $art$إذا لم ينفذ أحد المتعاقدين التزاماته، أو إذا فسخها فجأة وفي وقت غير لائق ومن غير
مبرر مقبول، ساغ إلزامه بالتعويضات لصالح المتعاقد الآخر، وهكذا فإن تغيب العامل قبل
إنهاء عمله، ثم جاء بعد انقضاء مدة خدمته يطالب بالأجر عن المدة التي عمل خلالها، ساغ
لرب العمل أن يدفع هذه المطالبة بالأضرار الناشئة له من انقطاع العمل ولا يلزمه إلا الفرق
إن وجد. وكذلك إذا وقعت مخالفة العقد من رب العمل، وجبت عليه التعويضات للعامل.
« يستفيد الأجراء، خلافا لمقتضيات الفصل1248 من الظهير الشريف المكون لقانون الالتزامات والعقود، من
امتياز الرتبة الأولى المقررة في الفصل المذكور، قصد استيفاء ما لهم من أجور، وتعويضات، في ذمة المشغل من
جميع منقولاته.
تكون التعويضات القانونية الناتجة عن الفصل من الشغل، مشمولة بنفس الامتياز، ولها نفس الرتبة .»
