العربية. وبذلك يمكن صياغة الفصل 799 :أعلاه كالآتي إذا أجريت الوديعة من ناقص الأهلية أو ممن أشهر
إعساره قضاء لم يسغ رد الشيء المودع إلا لمن ينوب عنه قانونا، وذلك لو كان نقص الأهلية أو الإعسار قد
حصل بعد إجراء الوديعة.
Si le dépôt a été fait par un incapable ou par un insolvable judiciairement
déclaré, il ne peut être restitué qu'à celui qui le représente légalement, même si
l'incapacité ou l'insolvabilité est postérieure à la constitution du dépôt.$art$, 846, $art$pdf-text-layer$art$, 0.415, 181, 181, $art$الفرع الثاني: التزامات المودع عنده$art$),
  ($art$803$art$, $art$الفصل 803$art$, $art$على المودع عنده أن يرد الشيء للمودع، ولو ادعى أحد من الغير حقا عليه، ما لم يكن
