أو تعديلها أو إسقاطها، من طرف محررها بسجل الوكالات المتعلقة بالحقوق العينية، ولا
تنتج آثارها القانونية إلا من تاريخ التقييد المذكور.
لا يحتج على الغير بالتعديلات المدخلة على عقد الوكالة أو بإلغائها، إلا من تاريخ
التقييد بالسجل المذكور.
يمسك سجل الوكالات الرسمية المتعلقة بالحقوق العينية على دعامة ورقية أو
إلكترونية، من طرف كتابة الضبط بالمحكمة الابتدائية التابع لها مكان تحرير العقد ويراقب
مسكه رئيس المحكمة أو القاضي المعين من طرفه.
يتم تقييد الوكالة الرسمية المنجزة بالخارج بالسجل الممسوك لدى كتابة الضبط
بالمحكمة المشار إليها في العقد، وفي حالة عدم الإشارة إلى ذلك تقيد هذه الوكالة بالسجل
الممسوك لدى كتابة الضبط بالمحكمة الابتدائية بالرباط أو بمكان تواجد العقار.
تحدد كيفيات تنظيم ومسك السجل المذكور بمقتضى نص تنظيمي.$art$, 934, $art$pdf-text-layer$art$, 0.677, 196, 196, $art$الباب الأول: الوَكالة بوجه عام$art$),
  ($art$889-2$art$, $art$الفصل 889-2$art$, $art$يحدث سجل وطني إلكترونيللوكالات يعهد بتدبيره إلى الإدارة، تتم من خلاله عملية
إشهار جميع الوكالات المضمنة بسجلات الوكالات المتعلقة بالحقوق العينية والممسوكة من
طرف كتابات الضبط بالمحاكم الابتدائية.
تتم من خلال السجل المذكور معالجة المعطيات المتعلقة بالوكالات المذكورة أعلاه،
عن طريق تجميعها وحفظها وتأمينها، في إطار التقيد بأحكام القانون رقم 09.08 المتعلق
بحماية الأشخاص الذاتيين تجاه معالجة المعطيات ذات الطابع الشخصي ، الصادر بتنفيذه
الظهير الشريف رقم 1.09.15 بتاريخ22 من صفر1430 (18 فبراير2009 ) والنصوص
المتخذة لتطبيقه.
