المدنية العقارية، كما يجب أن يقيد فيه كل فرع لهذه الشركة.
تكتسب الشركة المدنية في هذه الحالة، خلافا لمقتضيات الفصل 994 أدناه، الشخصية
الاعتبارية ابتداء من تاريخ تقييدها في السجل المشار إليه في الفقرة السابقة، ولا يحتج على
الغير بوجودها إلا من تاريخ هذا التقييد.
لا يحتج على الغير بالتقييدات المعدلة والتشطيبات، إلا من تاريخ إدراجها بالسجل
المذكور.
يسأل الأشخاص الذين قاموا بعمل باسم الشركة في طور التأسيس، قبل اكتسابها
الشخصية الاعتبارية، بصفة شخصية عن الأعمال التي تمت باسمها، ويترتب عن تقييد
الشركة في سجل الشركات المدنية العقارية تحملها التلقائي للالتزامات الناشئة عن تلك
الأعمال.
يمسك سجل الشركات المدنية العقارية، على دعامة ورقية أو إلكترونية، من طرف
كتابة الضبط بالمحكمة الابتدائية التابع لها عنوان مقر الشركة، و يراقب مسكه رئيس
المحكمة أو القاضي المعين من طرفه.
تحدد كيفيات تنظيم ومسك سجل الشركات المدنية العقارية بمقتضى نص تنظيمي.
