وعند الشك، يعتبر أن الشركاء قد قدموا حصصا متساوية.$art$, 1039, $art$pdf-text-layer$art$, 0.702, 217, 217, $art$الفرع الأول: القواعد العامة المتعلقة بالشركات المدنية والتجارية308$art$),
  ($art$991$art$, $art$الفصل 991$art$, $art$يلزم تعيين الحصة وتحديدها، وإذا تضمنت حصة أحد الشركاء كل أمواله الحاضرة
وجب إحصاء هذه الأموال. وإذا كانت الحصة أشياء أخرى غير النقود، لزم تقدير الأشياء
على حسب قيمتها في تاريخ وضعها في رأس المال. فإن لم تقم على هذا الوجه، اعتبر أن
الشركاء قد ارتضوا الركون إلى السعر الجاري للأشياء في تاريخ تقديم الحصة، فإن لم يكن
لهذه الأشياء سعر جار قدرت قيمتها وفق ما يقرره أهل الخبرة.
