لكل شريك أو مسير أن يوجه الدعوة لانعقاد جمعية الشركاء، خمسة عشر يوما قبل
تاريخ انعقادها على الأقل، ما لم ينص عقد الشركة على خلاف ذلك.
لجمعية الشركاء صلاحية اتخاذ كل القرارات أو إجراء تغييرات على عقد الشركة.
يحرر محضر بأشغال جمعية الشركاء يبين فيه تاريخ ومكان الاجتماع والأسماء
الشخصية والعائلية للشركاء الحاضرين والقرارات المتخذة خلاله.
يوقع المحضر من طرف جميع الشركاء الحاضرين.
يصحح إمضاء المسير على محضر جمعية الشركاء من قبل السلطات المختصة وتودع
نسخة منه مشهود بمطابقتها للأصل، بسجل الشركات المدنية العقارية داخل أجل شهر من
