  ($art$1026$art$, $art$الفصل 1026$art$, $art$لا يسوغ للمتصرفين، ولو انعقد إجماعهم، كما لا يسوغ لأغلبية الشركاء القيام بأعمال
أخرى غير الأعمال التي تدخل في غرض الشركة، على نحو ما تقتضيه طبيعتها وعرف318
.التجارة
ويلزم إجماع الشركاء:
أولا - لإجراء التبرع بأموال الشركة.؛
ثانيا - لإجراء تعديل في عقد الشركة أو لمخالفته؛
ثالثا - لإجراء الأعمال التي لا تدخل في غرض الشركة.
وكل شرط من شأنه أن يسمح مقدما للمتصرفين أو لأغلبية الشركاء باتخاذ قرارات
تتعلق بالأمور السابقة من غير استشارة باقي الشركاء يكون عديم الأثر. وفي كل هذه الأمور
يثبت حق الاشتراك في المداولات، حتى للشركاء الذين لا يتولون الإدارة. وعند الخلاف،
يلزم الأخذ برأي المعارضين.$art$, 1076, $art$pdf-text-layer$art$, 0.623, 225, 225, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1027$art$, $art$الفصل 1027$art$, $art$ليس للشركاء غير المتصرفين أن يتدخلوا في الإدارة. كما أنه لا يحق لهم الاعتراض
على الأعمال التي يجريها المتصرفون المعينون بمقتضى العقد، إلا إذا تجاوزت حدود
العمليات التي هي محل الشركة، أو تضمنت مخالفة واضحة للعقد أو القانون.$art$, 1077, $art$pdf-text-layer$art$, 0.731, 225, 225, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1028$art$, $art$الفصل 1028$art$, $art$للشركاء غير المتصرفين الحق في أن يطلبوا إخبارهم بكل ما يتعلق بإدارة شؤون
الشركة وحالة أموالها كما يحق لهم الاطلاع على دفاتر الشركة ومستنداتها وأخذ نسخ منها
وكل شرط يقضي بخلاف ذلك يكون عديم الأثر، وهذا الحق خاص بالشريك شخصيا فلا
تسوغ مباشرته بوساطة وكيل أو نائب مع استثناء حالة ناقصي الأهلية الذين يمثلهم قانونا
نوابهم القانونيون، والحالة التي يحول فيها دون مباشرة الشريك الحق بنفسه عائق مشروع
ومقبول.$art$, 1078, $art$pdf-text-layer$art$, 0.583, 225, 225, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1029$art$, $art$الفصل 1029$art$, $art$لاليس لمجرد الشريك بالمحاصة الحق في الإطلاع على دفاتر الشركة ومستنداتها، إ
إذا وجدت لهذا الاطلاع مبررات خطيرة وبإذن المحكمة.
318 - انظر الهامش المضمن في الفصل25 أعلاه.$art$, 1079, $art$pdf-text-layer$art$, 0.653, 225, 225, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1030$art$, $art$الفصل 1030$art$, $art$لا يجوز عزل المتصرفين المعينين بمقتضى عقد الشركة، إلا إذا وجدت له مبررات
معتبرة، وبشرط أن يتم بإجماع الشركاء.
إلا أنه يجوز أن يشترط في عقد الشركة منح هذا الحق للأغلبية أو أنه يمكن عزل
المتصرفين المعينين في العقد، كما لو كانوا مجرد وكلاء، وتعتبر مبررات للعزل الأعمال
التي تتضمن سوء الإدارة والخلافات الخطيرة التي تقع بين المتصرفين، والإخلال الجسيم
الواقع من واحد أو أكثر منهم في أداء واجبات مهامهم واستحالة قيامهم بهذه الواجبات.
ومن ناحية أخرى، لا يجوز للمتصرفين المعينين بمقتضى عقد الشركة أن يتخلوا عن
أداء وظائفهم، ما لم توجد هناك أسباب معتبرة تمنعهم منه، وإلا وجب عليهم التعويض لباقي
الشركاء. غير أنه يسوغ للمتصرفين الذين يمكن عزلهم وفقا لمشيئة الشركاء أن يتخلوا عن
وظائفهم في الحدود المقررة للوكلاء.$art$, 1080, $art$pdf-text-layer$art$, 0.618, 226, 226, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1031$art$, $art$الفصل 1031$art$, $art$إذا لم يكن الشركاء المتصرفون قد عينوا بمقتضى عقد الشركة، أمكن عزلهم، كما
يعزل مجرد الوكلاء، ولا يسوغ حينئذ تقرير العزل إلا بتوفر الأغلبية المتطلبة للتعيين.
ومن ناحية أخرى، يجوز للمتصرفين السابقين التخلي عن وظائفهم في الحدود المقررة
للوكلاء. وتسري أحكام هذا الفصل على المتصرفين إذا كانوا من غير الشركاء.$art$, 1081, $art$pdf-text-layer$art$, 0.617, 226, 226, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1032$art$, $art$الفصل 1032$art$, $art$إذا لم يتقرر شيء بخصوص إدارة شؤون الشركة، اعتبرت الشركة شركة عِنان،
ونظمت علاقات الشركاء في هذا الصدد وفقا لأحكام الفصل 1030.$art$, 1082, $art$pdf-text-layer$art$, 0.612, 226, 226, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1033$art$, $art$الفصل 1033$art$, $art$.نصيب كل شريك في الأرباح والخسائر يكون بنسبة حصته في رأس المال
إذا لم يحدد نصيب الشريك إلا في الأرباح، طبقت نفس النسبة في تحمله بالخسائر. وإذا
لم يحدد نصيبه إلا في الخسائر طبقت نفس النسبة على نصيبه في الأرباح.
وعند الشك، يفترض أن أنصباء الشركاء متساوية.
ويقدر نصيب الشريك الذي لم يقدم في رأس المال إلا عمله، بحسب أهمية هذا العمل
للشركة. والشريك الذي تتكون حصته في رأس المال، من النقود أو غيرها من القيم، زيادة
على عمله، يكون له نصيب يتناسب مع ما قدمه من المال والعمل معا.$art$, 1083, $art$pdf-text-layer$art$, 0.679, 226, 226, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1034$art$, $art$الفصل 1034$art$, $art$كل شرط من شأنه أن يمنح أحد الشركاء نصيبا في الأرباح أو في الخسائر أكبر من
النصيب الذي يتناسب مع حصته في رأس المال يكون باطلا ومبطلا لعقد الشركة نفسه،
وللشريك الذي يتضرر من وجود شرط من هذا النوع أن يرجع على الشركة في حدود ما لم
يقبضه من نصيبه في الربح، أو ما دفعه زائدا على نصيبه في الخسارة مقدرا في كلتا
الحالتين بنسبة حصته في رأس المال.$art$, 1084, $art$pdf-text-layer$art$, 0.796, 226, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1035$art$, $art$الفصل 1035$art$, $art$إذا تضمن العقد منح أحد الشركاء كل الربح، كانت الشركة باطلة، واعتبر العقد
متضمنا تبرعا ممن تنازل عن نصيبه في الربح، ويبطل الشرط الذي من شأنه إعفاء أحد
الشركاء من كل مساهمة في تحمل الخسائر، ولكن لا يترتب عليه بطلان العقد.$art$, 1085, $art$pdf-text-layer$art$, 0.61, 227, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1036$art$, $art$الفصل 1036$art$, $art$غير أنه يسوغ أن يشترط لمن قدم عمله حصة في رأس المال، نصيب في الأرباح أكبر
من أنصباء باقي الشركاء.$art$, 1086, $art$pdf-text-layer$art$, 0.676, 227, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1037$art$, $art$الفصل 1037$art$, $art$تتمتصفية حساب الأرباح والخسائر بعد تحرير الميزانية، التي يجب أن تحضر في
نفس الوقت مع إجراء الإحصاء، وذلك في آخر كل سنة مالية للشركة.$art$, 1087, $art$pdf-text-layer$art$, 0.658, 227, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1038$art$, $art$الفصل 1038$art$, $art$يجب اقتطاع جزء من عشرين من صافي أرباح كل سنة مالية للشركة، قبل إجراء أي
قسمة. ويستخدم هذا الجزء في تكوين صندوق الاحتياطي. ويستمر الاقتطاع إلى أن يصل
الاحتياطي إلى خمس رأس المال.
وإذا نقص رأس مال الشركة، وجبت إعادة تكوينه من الأرباح التالية لحد مبلغ
الخسائر. ويتوقف كل توزيع للأرباح بين الشركاء إلى أن يتم إعادة رأس المال كاملا. وذلك
ما لم يقرر هؤلاء إنقاص رأس مال الشركة إلى رأس المال الفعلي.$art$, 1088, $art$pdf-text-layer$art$, 0.631, 227, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1039$art$, $art$الفصل 1039$art$, $art$بعد إجراء الاقتطاع المنصوص عليه في الفصل السابق، يحدد نصيب الشركاء في
الأرباح. ولكل منهم أن يسحب نصيبه منها. فإن لم يسحبه، اعتبر وديعة عند الشركة، ولا
يضاف إلى حصته في رأس المال، ما لم يرتض باقي الشركاء ذلك صراحة. والكل ما لم
يتفق على خلافه.$art$, 1089, $art$pdf-text-layer$art$, 0.63, 227, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1040$art$, $art$الفصل 1040$art$, $art$في حالة الخسارة، لا يلتزم الشريك بأن يعيد إلى رأس مال الشركة نصيبه في الربح
عن سنة مالية سابقة، إذا كان قد قبضه بحسن نية، وفقا لميزانية حررت حسب الأصول
وبحسن نية أيضا.
وإذا لم تكن الميزانية قد حررت بحسن نية، ثبت للشريك غير المتصرف الذي اضطر
إلى أن يعيد إلى خزانة الشركة الأرباح التي سبق له أن قبضها بحسن نية، حق الرجوع
بالتعويض على متصرفي الشركة.$art$, 1090, $art$pdf-text-layer$art$, 0.631, 227, 227, $art$الفرع الثاني: آثار الشركة بين الشركاء وبالنسبة إلى الغير$art$),
  ($art$1041$art$, $art$الفصل 1041$art$, $art$إذا تأسست الشركة بقصد إجراء عمل محدد، فإن التصفية النهائية للحسابات وتوزيع
الأرباح لا يحصلان إلا بعد تنفيذ هذا العمل.
