  ($art$1051$art$, $art$الفصل 1051$art$, $art$:تنتهي الشركة
أولا - بانقضاء المدة المحددة لها أو حصول ما يقتضي فسخها من شرط أو غيره؛
ثانيا - بتحقق الأمر الذي أنشئت من أجله أو باستحالة تحققه؛
ثالثا - بهلاك المال المشترك هلاكا كليا، أو بهلاكه هلاكا جزئيا يبلغ من الجسامة حدا
بحيث يحول دون الاستغلال المفيد؛
رابعا - بموت أحد الشركاء أو بإعلان فقده قضاء أو بالحَجْر عليه ما لم يكن قد وقع
الاتفاق على استمرار الشركة مع ورثته أو نائبيه أو على استمرارها بين الباقين من الشركاء
على قيد الحياة؛
خامسا - بإشهار إفلاس319 أحد الشركاء أو تصفيته قضائيا؛
سادسا - باتفاق الشركاء جميعا؛
سابعا - بانسحاب واحد أو أكثر من الشركاء في حالة ما إذا كانت مدة الشركة غير
محددة، إما بمقتضى العقد، وإما بحسب طبيعة العمل الذي قامت الشركة لأجله؛
ثامنا - بحكم القضاء في الأحوال المنصوص عليها في القانون.
319 - انظر الهامش المضمن في الفصل116 أعلاه حول مساطر معالجة صعوبة المقاولة التي عوضت نظام
الإفلاس.$art$, 1101, $art$pdf-text-layer$art$, 0.659, 229, 229, $art$الفرع الثالث: حل الشركة وإخراج الشركاء منها$art$),
