  ($art$1111$art$, $art$الفصل 1111$art$, $art$:يجوز الطعن في الصلح
أولا: بسبب الإكراه أو التدليس؛
ثانيا: بسبب غلط مادي وقع في شخص المتعاقد الآخر، أو في صفته أو في الشيء الذي
كان محلا للنزاع؛
ثالثا: لانتفاء السبب إذا كان الصلح قد أجري:
331 - إن عبارة "عقد معاوضة" الواردة في آخر النص قد يفهم منها أي عقد معاوضة ولو كان هذا الأخير من
عقود الغَرَر، والحال أن المقصود في النص هو العقد المحدد الذي لا غَرَر فيه.
أ- على سند مزور؛
ب - على سبب غير موجود؛
ج - على نازلة سبق فصلها بمقتضى صلح صحيح أو حكم غير قابل للاستئناف أو
للمراجعة كان الطرفان أو أحدهما يجهل وجوده.
ولا يجوز في الحالات السابقة، التمسك بالبطلان، إلا للمتعاقد الذي كان حسن النية.$art$, 1161, $art$pdf-text-layer$art$, 0.656, 241, 242, $art$القسم التاسع: الصلح$art$),
  ($art$1112$art$, $art$الفصل 1112$art$, $art$لا يجوز الطعن في الصلح بسبب غلط في القانون، ولا يجوز الطعن فيه بسبب الغَبْن
إلا في حالة التدليس.$art$, 1162, $art$pdf-text-layer$art$, 0.639, 242, 242, $art$القسم التاسع: الصلح$art$),
  ($art$1113$art$, $art$الفصل 1113$art$, $art$إذا تصالح الطرفان بوجه عام على جميع ما كان بينهما من القضايا فإن المستندات التي
كانت مجهولة منهما حينذاك، والتي اكتشفت فيما بعد، لا تكون سببا لإبطال الصلح، ما لم
يكن هناك تدليس من المتعاقد الآخر.
ولا يسري هذا الحكم، إذا كان الصلح قد أجري من النائب القانوني لناقص الأهلية،
وكان النائب قد ارتضاه نتيجة عدم وجود المستند، ثم عثر عليه فيما بعد.$art$, 1163, $art$pdf-text-layer$art$, 0.582, 242, 242, $art$القسم التاسع: الصلح$art$),
  ($art$1114$art$, $art$الفصل 1114$art$, $art$الصلح لا يقبل التجزئة فبطلان جزء منه أو إبطاله يقتضيبطلانه أو إبطاله كله.
ولا يسري هذا الحكم:
أولا - إذا تبين من العبارات المستعملة أو من طبيعة الاشتراطات أن المتعاقدين قد
اعتبروا شروط الصلح أجزاء متميزة ومستقلة بعضها عن البعض الآخر؛
ثانيا - إذا نتج البطلان عن عدم توفر الأهلية لدى أحد المتعاقدين.
وفي هذه الحالة لا يستفيد من البطلان إلا ناقص الأهلية الذي تقرر لصالحه ما لم يكن
قد اشترط صراحة أنه يترتب على فسخ الصلح التحلل من حكمه بالنسبة إلى المتعاقدين
جميعا.$art$, 1164, $art$pdf-text-layer$art$, 0.639, 242, 242, $art$القسم التاسع: الصلح$art$),
  ($art$1115$art$, $art$الفصل 1115$art$, $art$فسخ الصلح يعيد المتعاقدين إلى نفس الحالة القانونية التي كانا عليها عند إبرامه ويخول
كلا منهما حق استرداد ما أعطاه تنفيذا للصلح، مع عدم الإخلال بالحقوق المكتسبة على وجه
صحيح وعلى سبيل المُعاوضة من طرف الغير حسني النية.
وإذا أصبحت مباشرة الحق الذي حصل التنازل عنه متعذرة، وقع الاسترداد على قيمته.$art$, 1165, $art$pdf-text-layer$art$, 0.612, 242, 242, $art$القسم التاسع: الصلح$art$),
  ($art$1116$art$, $art$الفصل 1116$art$, $art$إذا كان الاتفاق الذي سمي صلحا ، يتضمن في الحقيقة، وبرغم العبارات المستعملة،
هبة أو بيعا، أو أي علاقة قانونية أخرى، وجب أن تطبق على ذلك الاتفاق بالنسبة إلى صحته
وآثاره، الأحكام التي تنظم العقد الذي أبرم تحت اسم الصلح.$art$, 1166, $art$pdf-text-layer$art$, 0.714, 243, 243, $art$القسم التاسع: الصلح$art$),
  ($art$1117$art$, $art$الفصل 1117$art$, $art$الكفالة عقد بمقتضاه يلتزم شخص للدائن بأداء التزام المدين، إذا لم يؤده هذا الأخير
نفسه.$art$, 1167, $art$pdf-text-layer$art$, 0.562, 243, 243, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1118$art$, $art$الفصل 1118$art$, $art$من كلف شخصا بأن يداين أحدا من الغير، متعهدا بالمسؤولية عنه، ضمن، بصفته
كفيلا، الالتزامات المعقودة من هذا الغير، في حدود المبلغ الذي يعينه.
فإن لم يعين الكفيل حدا لما يضمنه، فإنه لا يسأل إلا في حدود المبلغ الذي يبدو معقولا،
مع مراعاة الشخص الذي منحت له الكفالة.
يسوغ الرجوع عن التكليف السابق، مادام الشخص المكلف لم يبدأ بتنفيذه ولا يمكن
إثبات التكليف إلا بالكتابة.$art$, 1168, $art$pdf-text-layer$art$, 0.628, 243, 243, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1119$art$, $art$الفصل 1119$art$, $art$لا يجوز لأحد أن يكفل دينا، ما لم يكن متمتعا بأهلية التفويت على سبيل التبرع.
لا تجوز الكفالة من القاصر ولو أذن له أبوه أو وصيه، إذا لم تكن له أي مصلحة في
موضوع الكفالة.$art$, 1169, $art$pdf-text-layer$art$, 0.614, 243, 243, $art$الباب الأول: الكفالة بوجه عام$art$),
