  ($art$1121$art$, $art$الفصل 1121$art$, $art$تجوز كفالة الالتزام المحتمل (كضمان الالتزام الذي قد ينشأ بسبب الاستحقاق) أو
المستقبل أو غير المحدد، بشرط أن يكون قابلا للتحديد فيما بعد (كالمبلغ الذي يمكن أن يحكم
به على شخص معين)، وفي هذه الحالة يتحدد التزام الكفيل بالتزام المدين الأصلي.$art$, 1171, $art$pdf-text-layer$art$, 0.682, 243, 243, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1122$art$, $art$الفصل 1122$art$, $art$لا يجوز كفالة الالتزام الذي لا يستطيع الكفيل أن يحل محل المدينالأصلي في أدائه
كالعقوبة البدنية.$art$, 1172, $art$pdf-text-layer$art$, 0.686, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
