يطلب تنفيذه، فإن لم ينفذ كان له الحق في التعويض.$art$, 1174, $art$pdf-text-layer$art$, 0.596, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1125$art$, $art$الفصل 1125$art$, $art$لا ضرورة لقبولالكفالة صراحة من الدائن، غير أنها لا يمكن أن تعطى برغم إرادته.$art$, 1175, $art$pdf-text-layer$art$, 0.632, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1126$art$, $art$الفصل 1126$art$, $art$يمكن كفالة الالتزام بغير علم المدين الأصلي ولو بغير إرادته. غير أن الكفالة التي تقدم
برغم الاعتراض الصريح من المدين، لا يترتب عنها أي علاقة قانونية بين هذا الأخير وبين
الكفيل، وإنما يكون ملتزما في مواجهة الدائن فقط.$art$, 1176, $art$pdf-text-layer$art$, 0.623, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1127$art$, $art$الفصل 1127$art$, $art$.لا تجوز كفالة المدين الأصلي فحسب، بل تجوز أيضا كفالة من كفل هذا المدين$art$, 1177, $art$pdf-text-layer$art$, 0.625, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1128$art$, $art$الفصل 1128$art$, $art$.لا يصح أن تتجاوز الكفالة ما هو مستحق على المدين، إلا فيما يتعلق بالأجل$art$, 1178, $art$pdf-text-layer$art$, 0.625, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1129$art$, $art$الفصل 1129$art$, $art$يصح أن تكون الكفالة لأجل، بمعنى أن تبرم لوقتمعلوم، أو ابتداء من تاريخ محدد،
ويسوغ أن تعقد ضمانا لجزء من الدين دون باقيه، وبشرط أخف من شروطه.$art$, 1179, $art$pdf-text-layer$art$, 0.744, 244, 244, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1130$art$, $art$الفصل 1130$art$, $art$إذا لم تكن الكفالة قد حددت صراحة بمبلغ معلوم، أو بجزء معين من الالتزام
المضمون، فإن الكفيل يضمن أيضا التعويضات والمصروفات التي يتحمل بها المدين
الأصلي بسبب عدم تنفيذ الالتزام.
ولا يضمن الكفيل الالتزامات الجديدة التي يعقدها المدين الأصلي بعد قيام الالتزام الذي
ضمنه.
غير أنه إذا ضمن الكفيل صراحة تنفيذ جميع الالتزامات التي يتحمل بها المدين،
بمقتضى عقد معين، فإنه يكون مسؤولا عن كل الالتزامات التي يسأل عنها هذا المدين نفسه
بمقتضى هذا العقد.$art$, 1180, $art$pdf-text-layer$art$, 0.615, 244, 245, $art$الباب الأول: الكفالة بوجه عام$art$),
