يقع باطلا. ويترتب عليه بطلان الكفالة نفسها.
ويستثنى من هذه القاعدة الكفالة التي تعقد بين التجار لأغراض التجارة، إذا سمح
العرف بإعطاء أجر عنها.$art$, 1181, $art$pdf-text-layer$art$, 0.615, 245, 245, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1132$art$, $art$الفصل 1132$art$, $art$لالإذا قبل الدائن، بمقتضى العقد، كفيلا معينا، ثم أعسر هذا الكفيل وجب أن يعطى كفي
آخر، أو ضمانة معادلة وإلا ساغ للدائن أن يطلب وفاء دينه فورا، أو أن يطلب فسخ العقد
الذي أبرمه تحت شرط تقديم الكفيل.
فإذا نقص ملاء الكفيل فقط وجب تقديم كفالة إضافية أو ضمانة تكميلية.
ولا تسري هذه الأحكام:
أولا: إذا كانت الكفالة قد عقدت بغير علم المدين أو برغم اعتراضه؛
ثانيا: إذا كانت الكفالة قد قدمت تنفيذا لاتفاق اشترط فيه الدائن تقديم شخص معين
للكفالة.$art$, 1182, $art$pdf-text-layer$art$, 0.605, 245, 245, $art$الباب الأول: الكفالة بوجه عام$art$),
  ($art$1133$art$, $art$الفصل 1133$art$, $art$الكفالة لا تقتضيالتضامن، ما لم يشترط صراحة.
وفي هذه الحالة الأخيرة، وفي الحالة التي تعتبر الكفالة فيها فعلا تجاريا بالنسبة إلى
الكفيل، تخضع آثار الكفالة للقواعد المتعلقة بالتضامن بين المدينين.$art$, 1183, $art$pdf-text-layer$art$, 0.603, 245, 245, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1134$art$, $art$الفصل 1134$art$, $art$لا يحق للدائن الرجوع على الكفيل إلا إذا كان المدين في حالة مَطْل في تنفيذ التزامه.$art$, 1184, $art$pdf-text-layer$art$, 0.67, 245, 245, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1135$art$, $art$الفصل 1135$art$, $art$:غير أنه
أولا: إذا مات الكفيل قبل حلول الأجل، حق للدائن الرجوع فورا على تركته، دون
ضرورة لانتظار حلوله. وإذا دفع الورثة الدين في هذه الحالة كان لهم أن يرجعوا على
المدين، عند حلول أجل الالتزام الأصلي؛
ثانيا: إشهار إفلاس332 الكفيليترتب عليه حلول أجل الدين بالنسبة إليه، حتى قبل حلول
أجل الالتزام الأصلي. وللدائن، في هذه الحالة أن يتقدم بدينه في تفليسة الكفيل؛
ثالثا: وفاة المدين تؤدي إلى حلول أجل الدين بالنسبة إلى تركته333 ولكن لا يسوغ للدائن
مطالبة الكفيل، قبل حلول الأجل المتفق عليه.$art$, 1185, $art$pdf-text-layer$art$, 0.609, 245, 246, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1136$art$, $art$الفصل 1136$art$, $art$للكفيل الحق في أن يطلب من الدائن أن يقوم أولا بتجريد المدين من أمواله المنقولة
والعقارية، بشرط أن تكون قابلة للتنفيذ عليها، وأن توجد في المغرب وأن يقوم بإرشاده إليها.
وعندئذ، تتوقف مطالبة الكفيل إلى أن تجرد أموال المدين الأصلي بدون إخلال بحق
الدائن في اتخاذ ما عساه أن يؤذن له به من الإجراءات التحفظية ضد الكفيل. وإذا كان للدائن
حق الرهن الحيازي أو الرهن بدون حيازة أو حق الحبس على منقول مملوك للمدين، وجب
عليه أن يستوفي دينه منه، ما لم يكن مخصصا لضمان ديون أخرى على المدين حالة كونه
غير كاف للوفاء بها جميعها.
332 - وردت في النص الفرنسي عبارة" d'insolvabilité déclaré" ""إشهار إعسار بدل "إشهار إفلاس"
كما جاء في الترجمة العربية.
-333إن عبارة "وفاة المدين تؤدي إلى حلول أجل الدين بالنسبة إلى تركته" يمكن اعتبارها لاغية نظرا لإلغاء
الفصل 140 .من قانون الالتزامات العقود
334 - تم تغييروتتميم الفقرة الثانية من المادة 1136 أعلاه، بمقتضى المادة 3 من القانون رقم21.18 ،السالف
الذكر.$art$, 1186, $art$pdf-text-layer$art$, 0.664, 246, 246, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1137$art$, $art$الفصل 1137$art$, $art$:ليس للكفيل طلب تجريد المدين الأصلي من أمواله
أولا: إذا كان قد تنازل صراحة عن التمسك بالدفع بالتجريد، وعلى الخصوص إذا كان
قد التزم متضامنا مع المدين الأصلي؛
ثانيا: إذا صعبت إلى حد كبير مطالبة المدين الأصلي واتخاذ إجراءات التنفيذ علي ه،
نتيجة تحويل محل إقامته أو موطنه أو مركز صناعته بعد قيام الالتزام؛
ثالثا: إذا كان المدين الأصلي في حالة إعسار بين أو إفلاس وقع إشهاره335؛
رابعا: إذا كانت الأموال التي يمكن تجريد المدين منها متنازعا عليها أو مثقلة برهون
رسمية تستغرق جزءا كبيرا من قيمتها، أو كان من الواضح أنها ليست كافية للوفاء بكل حق
الدائن، أو لم يكن للمدين عليها إلا حق قابل للفسخ.$art$, 1187, $art$pdf-text-layer$art$, 0.594, 247, 247, $art$الباب الثاني: آثار الكفالة$art$),
