كان الكفيل قد تحلل من الكفالة نتيجة تمسكه بدفوع شخصية محضة خاصة به.$art$, 1189, $art$pdf-text-layer$art$, 0.561, 247, 247, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1140$art$, $art$الفصل 1140$art$, $art$للكفيل أن يتمسك، في مواجهة الدائن، بكل دفوع المدين الأصلي، سواء كانت شخصية
