335 - وردت فيالنص الفرنسي عبارة "déconfiture." "إعسار" بدل "إفلاس" كما جاء في الترجمة العربية
في هذا الفصل يستعمل المشرع الإعسار بمعنى (insolvabilité) كما يستعمل الإعسار بمعنى
(déconfiture).
انظر عبد الرزاق السنهوري، الوسيط في شرح القانون المدني، ج2 ، دار إحياء التراثالعربي، بيروت، ص
1209 ؛ الذي ميز بين الإعسار الفعلي(insolvabilité) والإعسار القانوني(déconfiture) . فالإعسار الفعلي
حالة واقعية (état de fait) تنشأ عن زيادة ديون المدين- سواء كانت مستحقة الأداء أو غير مستحقة ما دامت
محققة الوجود – على حقوقه. أما الإعسار القانوني فحالة قانونية (état de droit) تنشأ من زيادة ديون المدين
المستحقة الأداء على حقوقه، ولا بد من شهرها بموجب حكم قضائي يجعل المدين في حالة إعسار (état de
déconfiture).$art$, 1190, $art$pdf-text-layer$art$, 0.573, 247, 247, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1141$art$, $art$الفصل 1141$art$, $art$:للكفيل مقاضاة المدين الأصلي للحصول على إبراء ذمته من التزامه
أولا: إذا وقعت عليه الدعوى قضاء من أجل الوفاء بالدين أو حتى قبل أن توجه إليه أي
مطالبة، إذا كان المدين في حالة مَطْل في تنفيذ الالتزام؛
ثانيا: إذا كان المدين قد التزم بأن يقدم للكفيل إبراء ذمته من الدائن خلال أجل محدد، ثم
حل هذا الأجل. وإذا لم يتمكن المدين من تقديم إبراء الذمة من طرف الدائن، وجب عليه أن
يدفع الدين أو أن يعطي الكفيل رهنا حيازيا أو رهنا بدون حيازة أو رهنا رسميا أو ضمانة
أخرى كافية336 ؛
ثالثا: إذا صعبت مطالبة المدين إلى حد كبير، نتيجة تحويل محل إقامته أو موطنه أو
مركز صناعته.
وليس للكفيل الذي يوجد في إحدى الحالات المنصوص عليها في الفصل 1147 أن
يتمسك بمقتضيات الأحكام السابقة.$art$, 1191, $art$pdf-text-layer$art$, 0.674, 248, 248, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1142$art$, $art$الفصل 1142$art$, $art$للكفيل أن يرجع على الدائن، من أجل إبراء ذمته من الدين، بمجرد تأخره عن المطالبة
به، بعد أن يصبح مستحق الأداء.$art$, 1192, $art$pdf-text-layer$art$, 0.721, 248, 248, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1143$art$, $art$الفصل 1143$art$, $art$للكفيل الذي يقضي الالتزام الأصلي قضاء صحيحا حق الرجوع على المدين بكل ما
دفعه عنه، ولو كانت الكفالة قد أعطيت بغير علمه، وله حق الرجوع عليه أيضا من أجل
المصروفات والخسائر التي كانت نتيجة طبيعية وضرورية للكفالة.
كل فعل يصدر عن الكفيل وليس وفاء بمعناه الحقيقي وإنما يترتب عليه انقضاء الالتزام
الأصلي وبراءة ذمة المدين، يقع بمثابة الوفاء، ويعطى الكفيل حق الرجوع من أجل أصل
الدين والمصروفات المتعلقة به.$art$, 1193, $art$pdf-text-layer$art$, 0.567, 248, 248, $art$الباب الثاني: آثار الكفالة$art$),
  ($art$1144$art$, $art$الفصل 1144$art$, $art$ليس للكفيل الذي أدى الدين حق الرجوع على المدين الأصلي، إلا إذا أمكنه أن يقدم
توصيلا من الدائن، أو أي حجة أخرى تثبت انقضاء الدين.
ليس للكفيل الذي أدى الدين قبل حلول الأجل حق الرجوع على المدين إلا بعد حلول
أجل الالتزام الأصلي.
