المبالغ المستحقة. ويمكن أن يتضمن هذا الإنذار التنصيص على سقوط أجل باقي الأقساط في
حالة عدم الأداء، وكذا إمكانية تحقيق الضمانة تبعا لذلك.
يحدد الإنذار المذكور أجلا يجب ألا يقل عن (15 ) يوما من تاريخ تبليغه، من أجل
تمكين المدين من الوفاء بالمبالغ المستحقة. وفي حالة عدم الأداء وانقضاء الأجل، أمكن
للدائن مباشرة إجراءات تحقيق الضمانة.
يجب أن يقوم الدائن المرتهن بعد انقضاء الأجل المذكور، بتقييد الإنذار الموجه من
قبله، في السجل الوطني الإلكتروني للضمانات المنقولة الذي يشعر فورا باقي الدائنين
المرتهنين المسجلين.
وفي حالة ما إذا تعلق الأمر برهن حياز ي، وجب على الدائن المرتهن إشعار
المستفيدين منه بنيته في تحقيق الرهن، كلما كان ذلك متاحا.
ويتعين على الراهن أو الغير الحائز، حسب الحالة، الامتناع عن التصرف في الأشياء
المرهونة، أو القيام بأي تدبير من شأنه إنقاص قيمتها، دون موافقة الدائن، وذلك تحت طائلة
تحمله المسؤولية عن ذلك.
376 - تم استدراك الخطأ المادي الذي وقع في الفصل المحال عليه أعلاه وأصبح يقرأ1222 بدلا من1221؛
الجريدة الرسمية عدد 6840 بتاريخ22 ربيع الآخر 1441 (19 ديسمبر 2019 )، ص11496.$art$, 1272, $art$pdf-text-layer$art$, 0.614, 265, 265, $art$الفرع الرابع: تحقيق الرهن الحيازي والرهن بدون حيازة375$art$),
