قاضي الأمور المستعجلة.
التعرض يوقف إجراءات تحقيق الشيء المرهون.
للدائن المرتهن إذا انقضى الأجل المذكور، ولم يقع تعرض أو وقع ولم يقبل أو رفض،
أن يستمر في إجراءات تحقيق الأشياء المرهونة.$art$, 1273, $art$pdf-text-layer$art$, 0.622, 266, 266, $art$الفرع الرابع: تحقيق الرهن الحيازي والرهن بدون حيازة375$art$),
  ($art$1221$art$, $art$الفصل 1221$art$, $art$يجوز أن يتفق الدائن المرتهن رهنا حيازيا أو الدائن المرتهن رهنا بدون حيازة مع
الراهن، عند إنشاء الرهن، على أنه في حالة عدم أداء الدين المضمون، يصبح الدائن مالكا
للشيء المرهون.
في حالة الرهن الحيازي، يبقى الشيء المرهون بيد الدائن المرتهن، ويتملكه بمجرد
ثبوت عدم الأداء.
وفي حالة الرهن بدون حيازة، يتملك الدائن المرتهن الشيء المرهون بمجرد ثبوت عدم
الأداء. ويتعين إثر ذلك على الراهن تسليم الشيء المرهون إلى الدائن المرتهن تحت طائلة
اللجوء إلى قاضي الأمور المستعجلة من أجل ذلك.
تحدد قيمة الشيء المرهون في تاريخ التملك باتفاق بين الدائن المرتهن والراهن.
إذا كان الرهن يتكون من عدة عناصر وجب تحديد قيمة كل عنصر على حدة.
وفي حالة عدم الاتفاق بينهما على القيمة، يتم تعيين خبير لهذه الغاية بالتراضي بينهما.
وإذا تعذر ذلك، يتم اللجوء إلى قاضي الأمور المستعجلة لاستصدار أمر من أجل تعيينه
قصد تحديد القيمة.
عندما يكون الشيء المرهون مدرجا في سوق مقننة، تحدد قيمة هذا الشيء في تاريخ
التملك على أساس سعر الإغلاق الأخير في هذه السوق.
وعندما تفوق القيمة المحددة مبلغ الدين المضمون، يؤدى للراهن مبلغ يساوي الفرق
بينهما، مع مراعاة أحكام الفصل 1-1227 377 أدناه.
