  ($art$1248$art$, $art$الفصل 1248$art$, $art$الديون الممتازة على كل المنقولات هي التيستذكر فيما بعد، وهي تباشر وفقا للترتيب
التالي:
أولا: مصروفات الجنازة، أي نفقات غسل الجثة وتكفينها ونقلها ودفنها مع مراعاة
المركز المالي للمدين الميت؛
ثانيا: الديون الناشئة عن مصروفات مرض الموت أيا ما كانت وسواء كانت قد أنفقت
في منزل المريض أو في مؤسسة علاجية عامة أو خاصة، وذلك خلال الستة أشهر السابقة
على الوفاة أو على افتتاح التوزيع؛
ثانيا مكرر394 : الديون الناشئة عن مهر الزوجة ومتعتها، المراعى في تقديرها ما قد
يلحق الزوجة من أضرار بسبب الطلاق غير المبرر، ونفقتها ونفقة الأولاد والأبوين395؛
393 - ظهير18 ديسمبر1947 وظهير6 يوليوز1954 وظهير2 أبريل1955.
394 - أضيفت هذه الفقرة بمقتضى الظهير الشريف معتبر بمثابة قانون رقم1.93.345 الصادر في22 من ربيع
الأول 1414 (10 سبتمبر1993 ) بتتميم قانون الالتزامات والعقود. الجريدة الرسمية عدد4222 بتاريخ 12 ربيع
الآخر 1414 (29 سبتمبر1993 )، ص1832.
395 - تنص المادة262 :من مدونة الأسرة على أنه
في حالة وفاة الوصي أو المقدم أو فقد أهليته المدنية يتخذ القاضي المكلف بشؤون القاصرين الإجراءات الملائمة
لحماية وصيانة أموال المحجور.
تخول الديون والتعويضات المستحقة للمحجور على تركة الوصي أو المقدم المتوفى امتيازا يرتب في المرتبة
المنصوص عليها في المقطع الثاني مكرر من المادة 1248 من الظهير الشريف المؤرخ في12 غشت1913
.المكون لقانون الالتزامات والعقود
:ثالثا المصروفات القضائية، كمصروفات وضع الأختام وإجراء الإحصاء والبيع
وغيرها مما يلزم للمحافظة على الضمان العام ولتحقيقه؛
رابعا396: الأجور، والتعويضات عن العطل المستحقة الأجرة، والتعويضات المستحقة
بسبب الإخلال بوجوب الإعلام بفسخ العقد داخل المهلة القانونية والتعويضات المستحقة إما
عن الفسخ التعسفي لعقد إجارة الخدمات وإما عن الإنهاء السابق لأوانه لعقد محدد المدة متى
كانت مستحقة:
أ – للخدام؛
ب - للعمال المستخدمين مباشرة من المدين؛
ج - للكتبة والمستخدمين والمكلفين، سواء كانت لهم رواتب محددة أو كانت أجورهم
محددة بعمولة نسبية؛
د - للفنانين الدراماتيكيين الممثلين وغيرهم من الأشخاص المستخدمين في مؤسسات
المشاهد العامة؛
ه - للفنانين وغيرهم من الأشخاص المستخدمين في محلات إنتاج الأفلام السينمائية.
والكل بالنسبة إلى الأجور المستحقة لهم عن الستة أشهر السابقة على الوفاة أو
الإفلاس397 أو التوزيع، أو، إذا كان الأجراء قد باشروا المطالبة القضائية ضد رب العمل قبل
الوفاة أو الإفلاس أو التوزيع، بالنسبة إلى ما عساه أن يكون مستحقا لهم من أجور عن الستة
أشهر الأخيرة. ويطبق نفس الحكم على توريدات المواد الغذائية للمدين أو لعائلته.
غير أنه يطبق ما يأتي في دفع الحصة غير القابلة للحجز عليها من التعويضات
المذكورة في الفقرة الأولى من هذا البند ومن المبالغ التي لازالت مستحقة:
من الأجور المكتسبة فعلا للعمال المستخدمين مباشرة، من المدين، أو للخدم، عن
الثلاثين يوما الأخيرة؛
من العمولة المستحقة للمتجولين والممثلين التجاريين عن التسعين يوما الأخيرة من
العمل؛
من الأجور المستحقة للبحارة عن فترة الوفاء الأخيرة.
والحصة غير القابلة للحجز عليها من التعويضات المذكورة آنفا تحسب مستقلة عن
الحصة غير القابلة للحجز عليها من الأجور.
396 - قارن مع المادة382 :من مدونة الشغل الذي ينص على أنه « يستفيد الأجراء، خلافا لمقتضيات الفصل
1248 من الظهير الشريف المكون لقانون الالتزامات والعقود، من امتياز الرتبة الأولى الم قررة في الفصل
المذكور، قصد استيفاء ما لهم من أجور، وتعويضات، في ذمة المشغل من جميع منقولاته.
تكون التعويضات القانونية الناتجة عن الفصل من الشغل، مشمولة بنفس الامتياز، ولها نفس الرتبة.»
397 - انظر الهامش المتضمن في الفصل116 أعلاه، حول مساطر معالجة صعوبة المقاولة التي عوضت نظام
الإفلاس.
وإن وفاء تلك الحصة غير القابلة للحجز عليها، وا لتي تمثل الفرق بين الأجور
والعمولات والتعويضات المستحقة وبين الحصة القابلة للحجز عليها منها، يجب أن يتم
بالرغم عن وجود أي دين آخر خلال العشرة أيام التالية لحكم شهر الإفلاس398 أو التصفية
القضائية بناء على مجرد الأمر من قاضي التفليسة، بشرط واحد، هو أن يوجد في يد السنديك
أو المصفي النقود اللازمة.
فإن لم يتوافر هذا الشرط لزم دفع الحصص السابقة من الأجور والعمولات
والتعويضات من أول نقود تدخل في يد السنديك أو المصفي، دون اعتبار لوجود أي دين
ممتاز آخر أو لمرتبته.
وفي حالة الإفلاس399 أو التصفية القضائية، إذا دفعت الحصةغير القابلة للحجز عليها
من الأجور والعمولات والتعويضات التي مازالت مستحقة على المدين للعمال والمستخدمين
والمتجولين والممثلين التجاريين، وفقا للأسس المبينة فيما سبق، من نقود سبقها السنديك أو
المصفي أو أي شخص آخر غيرهما، فإن المقرض يحل في الأجور المدفوعة محل
مستحقيها، ويحق له استيفاؤها بمجرد وجود النقود اللازمة من غير أن يكون لأي دائن آخر
أن يتعرض لذلك.
خامسا: الدين المستحق للمصاب في حادثة شغل أو لخلفائه والمتعلق بالمصروفات
الطبية والجراحية والصيدلية ومصروفات الجنازة وكذلك التعويضات المستحقة له نتيجة
العجز المؤقت عن العمل؛
سادسا: التعويضات المدفوعة للعمال والمستخدمين إما من صندوق الإسعاف
الاجتماعي أو أي مؤسسة أخرى تقوم بتقديم التعويضات العائلية للمشتركين فيها، وإما من
أرباب الأعمال الذين يقومون مباشرة بتقديم التعويضات العائلية لموظفيهم؛
سابعا - الديون المستح قة لصندوق الإسعاف الاجتماعي وغيره من المؤسسات التي
تقوم بتقديم التعويضات العائلية للمشتركين فيها، من أجل رسوم العضوية أو الاشتراكات
التي يلتزم هؤلاء المشتركون بدفعها للمنظمات السابقة وكذلك من أجل الإضافات التي
تقتضيها تلك الاشتراكات ورسوم العضوية400.
398 - انظر الهامش المضمن في الفصل116 أعلاه، حول مساطر معالجة صعوبة المقاولة التي عوضت نظام
الإفلاس.
399 - انظر الهامش المضمن في الفصل116 أعلاه حول مساطر معالجة صعوبة المقاولة التي عوضت نظام
الإفلاس.
400 - أنظر المادة 53 من القانون رقم 28.08 المتعلق بتعديل القانون المنظم لمهنة المحاماة الصادر بتنفيذه
الظهير الشريف رقم 1.08.101 بتاريخ20 من شوال1429 (20 أكتوبر2008 )، التي تضع أتعاب المحامي في
الرتبة الثامنة ضمن ترتيب الديون الممتازة على المنقولات المنصوص عليه في الفصل 1248 من قانون
الالتزامات والعقود؛ الجريدة الرسمية عدد 5680 بتاريخ7 ذو القعدة1429 (6 نوفمبر2008 ) ص4044.$art$, 1308, $art$pdf-text-layer$art$, 0.636, 275, 277, $art$الفرع الأول: الديون الممتازة على كل المنقولات$art$),
  ($art$1249$art$, $art$الفصل 1249$art$, $art$الدائن المُرتَهِن رهنا حيازيا أو الدائن المرتهن رهنا بدون حيازة لمنقول مقدم على
غيره في المتحصل من الشيء المرهون401 .$art$, 1309, $art$pdf-text-layer$art$, 0.682, 278, 278, $art$الفرع الثاني: الديون المضمونة برهن حيازي أو بامتياز خاص وارد$art$),
  ($art$1250$art$, $art$الفصل 1250$art$, $art$الديون الممتازة على بعض المنقولات هي المذكورةفيما يلي:
أولا: المبالغ المستحقة عن البذور وعن أعمال الفلاحة، وعن أعمال الحصاد لها امتياز
على الغلة؛
ثانيا: أجرة كراء الأراضي الفلاحية وغيرها من العقارات، والمبالغ المستحقة لصاحب
الإيراد المرتبة لمنح المنفعة لها امتياز على غلة السنة وعلى الغلة الناتجة من العقار
الموجودة في المحلات والمباني المكتراة، وعلى ما يستخدم في استغلال الأرض أو في
تجهيز المحلات المكتراة. ولا يثبت هذا الامتياز إلا من أجل ما استحق من الأجرة والإيراد
يوم الإعسار أو الإفلاس402 ، وما يستحق منهما عن الثلاثين يوما التالية ولكنه لا يمتد إلى
الغلة والبضائع التي أخرجت من الأماكن المكتراة، إذا كان هناك حق مكتسب لصالح الغير،
ما لم يكن إخراجها حاصلا بطريق الغش؛
ثالثا: المصروفات المنفقة لحفظ الشيء وهي التي لولاها لهلك الشيء أو أصبح غير
صالح لما أعد له، لها امتياز على المنقولات التي تم حفظها؛
رابعا: أجر الصانع عن عمله وما أنفقه من أجل المصنوع له امتياز على الأشياء التي
سلمت إليه مادامت في حوزته؛
خامسا: المبالغ المستحقة للوكيل بالعمولة لها امتياز على قيمة البضائع المرسلة في
الحدود المقررة في الفصل 919؛
سادسا: المبالغ المستحقة للناقل، من أجل ثمن النقل، ومن أجل ما أنفقه لها امتياز على
الأشياء المنقولة، مادامت في حوزته؛
سابعا: ديون أصحاب الفنادق والنزل ومن يسكنون غيرهم بسبب ما قدموه للنزيل أو
صرفوه لحسابه لها امتياز على أمتعة النزيل مادامت في النزل أو الفندق؛
ثامنا: (ظهير 20 نوفمبر1936 ) الديون الناشئة عن حادثة لصالح الأشخاص الذين
تضرروا منها أو لخلفائهم لها امتياز على مبلغ التأمين الذي يستحق على المؤمن عن
401 - تم نسخ تعويض المادة1249 أعلاه، بمقتضى المادة 5 من القانون رقم21.18 ،السالف الذكر.
402 - انظر الهامش المضمن في الفصل116 أعلاه حول مساطر معالجة صعوبة المقاولة التي عوضت نظام
الإفلاس.
المسؤولية المدنية، نتيجة اعترافه بأنه مدين بهذا المبلغ أو الحكم عليه به على أساس عقد
التأمين. ولا يبرئ ذمة المؤمنين أي وفاء يحصل للمؤمن له مادام الدائنون الممتازون لم
يستوفوا حقوقهم بعد.
تاسعا: (ظهير 18 دجنبر1947) الديون الناشئة عن عقد الشغل المبرم من طر ف
مساعد مأجور لعامل منزلي ينطبق عليه تعريف الفصل الثالث من ظهير 2 يوليوز1947
(2 شعبان1366) المتضمن ضابط الشغل403.
وتنطبق على دين المساعد المأجور لهذا العامل المنزلي المقتضيات المنصوص عليها
في الفقرات الثلاث الأخيرة من البند الرابع من الفصل 1248.
927091904
403 - نسخت المادة586 من مدونة الشغل مقتضياتظهير 2 يوليوز1947 (2 شعبان1366 ) المضمن ضابط
الشغل المذكور أعلاه.
